"""Sort semantic version strings by SemVer 2.0.0 precedence."""


def _identifier_key(identifier):
    # Numeric identifiers sort before alphanumeric ones; numerics compare as
    # integers, alphanumerics compare in ASCII order.
    if identifier.isdigit():
        return (0, int(identifier), "")
    return (1, 0, identifier)


def _precedence_key(version):
    # Build metadata (after '+') is ignored for ordering.
    main = version.split("+", 1)[0]

    # Pre-release begins at the first hyphen; the core has no hyphens.
    if "-" in main:
        core, pre = main.split("-", 1)
    else:
        core, pre = main, None

    major, minor, patch = (int(part) for part in core.split("."))

    if pre is None:
        # A release version is greater than any pre-release of the same version.
        pre_key = (1,)
    else:
        # Tuples give left-to-right comparison, and a shorter list that is a
        # prefix of a longer one sorts lower.
        pre_key = (0, tuple(_identifier_key(p) for p in pre.split(".")))

    return (major, minor, patch, pre_key)


def sort_versions(vs):
    """Return the version strings in vs sorted lowest precedence first.

    Versions that compare equal keep their input order (sorted() is stable).
    """
    return sorted(vs, key=_precedence_key)
